define(['core/log'],function(Log){var MAX_TEXT_RESPONSE_BYTES=1024*1024;var FETCH_TEXT_TIMEOUT_MS=10000;function safeInt(value,fallback){var parsed=parseInt(value,10);return Number.isFinite(parsed)?parsed:fallback;}function pad(value){value=Math.max(0,Math.floor(value));return value<10?'0'+value:''+value;}function formatSeconds(seconds){seconds=Math.max(0,Math.round(Number(seconds)||0));var hours=Math.floor(seconds/3600);var minutes=Math.floor((seconds%3600)/60);var secs=seconds%60;if(hours>0){return hours+':'+pad(minutes)+':'+pad(secs);}return pad(minutes)+':'+pad(secs);}function validateTextResponse(response){if(!response.ok){return Promise.reject(response.status);}if(response.redirected){return Promise.reject('redirected-response');}if(response.url&&!isSafeFetchUrl(response.url)){return Promise.reject('unexpected-response-url');}var contentType=(response.headers.get('content-type')||'').toLowerCase();var length=parseInt(response.headers.get('content-length')||'0',10);var responsePath='';try{responsePath=new URL(response.url||'',window.location.href).pathname.toLowerCase();}catch(e){responsePath='';}if(Number.isFinite(length)&&length>MAX_TEXT_RESPONSE_BYTES){return Promise.reject('response-too-large');}if(!/\.vtt$/.test(responsePath)){return Promise.reject('unexpected-content-type');}if(contentType&&contentType.indexOf('text/vtt')===-1&&contentType.indexOf('text/plain')===-1&&contentType.indexOf('application/octet-stream')===-1){return Promise.reject('unexpected-content-type');}return response.text().then(function(text){var sample;if(text.length>MAX_TEXT_RESPONSE_BYTES){return Promise.reject('response-too-large');}sample=text.replace(/^\uFEFF/,'').replace(/^\s+/,'').substring(0,64).toUpperCase();if(sample.indexOf('WEBVTT')!==0){return Promise.reject('unexpected-text-content');}return text;});}function isSafeFetchUrl(url){if(!url){return false;}var raw=String(url).trim();if(raw===''||raw.length>2048||/[\\\r\n]/.test(raw)){return false;}try{var parsed=new URL(raw,window.location.href);if(parsed.origin!==window.location.origin||(parsed.protocol!=='http:'&&parsed.protocol!=='https:')||parsed.username||parsed.password||parsed.hash){return false;}var path=decodeURIComponent(parsed.pathname).replace(/\\/g,'/').replace(/\/+/g,'/').toLowerCase();if(/(?:^|\/)\.\.(?:\/|$)/.test(path)){return false;}var isTextTrack=/(?:^|\/)[^/?#]+\.vtt$/.test(path);var isPluginFile=path.indexOf('/pluginfile.php/')!==-1||path.indexOf('/webservice/pluginfile.php/')!==-1;return isTextTrack&&isPluginFile;}catch(e){return false;}}function isSafeBeaconUrl(url){if(!url){return false;}var raw=String(url).trim();if(raw===''||raw.length>2048||/[\\\r\n]/.test(raw)){return false;}try{var parsed=new URL(raw,window.location.href);if(parsed.origin!==window.location.origin||(parsed.protocol!=='http:'&&parsed.protocol!=='https:')||parsed.username||parsed.password||parsed.hash){return false;}var path=decodeURIComponent(parsed.pathname).replace(/\/+/g,'/');if(/(?:^|\/|\\)\.\.(?:\/|\\|$)/.test(path)){return false;}if(!/\/lib\/ajax\/service\.php$/.test(path)){return false;}return parsed.searchParams.has('sesskey');}catch(e){return false;}}function fetchTextWithTimeout(url){if(typeof window.fetch!=='function'){return Promise.reject('fetch-unavailable');}if(!isSafeFetchUrl(url)){return Promise.reject('unsafe-url');}var options={credentials:'same-origin',mode:'same-origin',redirect:'error',headers:{'X-Requested-With':'XMLHttpRequest'}};if(window.AbortController){var controller=new AbortController();var timer=null;options.signal=controller.signal;timer=window.setTimeout(function(){controller.abort();},FETCH_TEXT_TIMEOUT_MS);return window.fetch(url,options).then(function(response){return validateTextResponse(response);}).catch(function(error){if(error&&error.name==='AbortError'){return Promise.reject('timeout');}return Promise.reject(error);}).then(function(text){window.clearTimeout(timer);return text;},function(error){window.clearTimeout(timer);return Promise.reject(error);});}var timeoutId=null;var fetchPromise=window.fetch(url,options).then(function(response){return validateTextResponse(response);}).then(function(text){if(timeoutId!==null){window.clearTimeout(timeoutId);timeoutId=null;}return text;},function(error){if(timeoutId!==null){window.clearTimeout(timeoutId);timeoutId=null;}return Promise.reject(error);});var timeoutPromise=new Promise(function(resolve,reject){timeoutId=window.setTimeout(function(){timeoutId=null;reject('timeout');},FETCH_TEXT_TIMEOUT_MS);});return Promise.race([fetchPromise,timeoutPromise]);}function sessionSet(key,value,context){try{if(!key||!window.sessionStorage){return Promise.resolve();}window.sessionStorage.setItem(String(key),String(value));}catch(error){Log.debug('mod_videotrack: could not save '+(context||'session state')+' - '+error);}return Promise.resolve();}function sessionGet(key,context){var value=null;try{if(!key||!window.sessionStorage){return null;}value=window.sessionStorage.getItem(String(key));}catch(error){Log.debug('mod_videotrack: could not read '+(context||'session state')+' - '+error);}return value;}return{safeInt:safeInt,formatSeconds:formatSeconds,fetchTextWithTimeout:fetchTextWithTimeout,isSafeBeaconUrl:isSafeBeaconUrl,sessionSet:sessionSet,sessionGet:sessionGet};});
